// main.ts
var DEFAULT_SETTINGS = {
  desktopPort: 9e3,
  autoRefresh: true
};
var TaskPlugin = class extends import_obsidian.Plugin {
  constructor() {
    super(...arguments);
    this.wasmReady = false;
  }
  async onload() {
    await this.loadSettings();
    await __wbg_init(task_vault_core_bg_default);
    this.wasmReady = true;
    this.addCommand({
      id: "create-task",
      name: "Create task",
      callback: () => this.createTaskInActiveFile()
    });
    this.addCommand({
      id: "validate-frontmatter",
      name: "Validate task frontmatter",
      checkCallback: (checking) => {
        const file = this.app.workspace.getActiveFile();
        if (!file || file.extension !== "md")
          return false;
        if (!checking)
          this.validateActiveFile(file);
        return true;
      }
    });
    this.addCommand({
      id: "sort-by-urgency",
      name: "Sort task list by urgency",
      callback: () => this.sortOpenTasksByUrgency()
    });
    if (this.settings.autoRefresh) {
      this.registerEvent(
        this.app.vault.on("modify", (file) => {
          if (file instanceof import_obsidian.TFile && file.extension === "md") {
            this.onMarkdownModified(file);
          }
        })
      );
      this.registerEvent(
        this.app.vault.on("create", (file) => {
          if (file instanceof import_obsidian.TFile && file.extension === "md") {
            this.onMarkdownModified(file);
          }
        })
      );
    }
    this.addSettingTab(new TaskSettingTab(this.app, this));
    console.log("Task plugin loaded");
  }
  onunload() {
    console.log("Task plugin unloaded");
  }
  // ── Vault helpers ─────────────────────────────────────────────────────────
  /**
   * Called whenever a markdown file is modified.
   * Parses its frontmatter via WASM and validates the task schema if present.
   */
  async onMarkdownModified(file) {
    if (!this.wasmReady)
      return;
    const content = await this.app.vault.read(file);
    const yaml = extractFrontmatter(content);
    if (!yaml)
      return;
    const error = validate_task(yaml);
    if (error) {
      console.debug(`[task] ${file.path}: ${error}`);
    }
  }
  /** Parse the YAML frontmatter of a file and return it as a task JSON string. */
  async readTaskJson(file) {
    if (!this.wasmReady)
      return null;
    const content = await this.app.vault.read(file);
    const yaml = extractFrontmatter(content);
    if (!yaml)
      return null;
    const json = parse_task_yaml(yaml);
    if (json.startsWith('{"error"'))
      return null;
    return json;
  }
  /** Collect all task JSON objects from markdown files in the vault. */
  async allTasksJson() {
    const files = this.app.vault.getMarkdownFiles();
    const results = [];
    for (const file of files) {
      const json = await this.readTaskJson(file);
      if (json)
        results.push(json);
    }
    return results;
  }
  // ── Command implementations ───────────────────────────────────────────────
  async createTaskInActiveFile() {
    const file = this.app.workspace.getActiveFile();
    if (!file) {
      new import_obsidian.Notice("No active file.");
      return;
    }
    const content = await this.app.vault.read(file);
    if (extractFrontmatter(content) !== null) {
      new import_obsidian.Notice("File already has frontmatter.");
      return;
    }
    const title = file.basename;
    const frontmatter = [
      "---",
      `title: "${title}"`,
      "status: Open",
      "priority: Normal",
      "---",
      ""
    ].join("\n");
    await this.app.vault.modify(file, frontmatter + content);
    new import_obsidian.Notice(`Task created: ${title}`);
  }
  async validateActiveFile(file) {
    if (!this.wasmReady)
      return;
    const content = await this.app.vault.read(file);
    const yaml = extractFrontmatter(content);
    if (!yaml) {
      new import_obsidian.Notice("No frontmatter found.");
      return;
    }
    const error = validate_task(yaml);
    if (error) {
      new import_obsidian.Notice(`Invalid task: ${error}`);
    } else {
      new import_obsidian.Notice("Task frontmatter is valid.");
    }
  }
  async sortOpenTasksByUrgency() {
    if (!this.wasmReady)
      return;
    const jsons = await this.allTasksJson();
    if (jsons.length === 0) {
      new import_obsidian.Notice("No tasks found in vault.");
      return;
    }
    const arrayJson = `[${jsons.join(",")}]`;
    const sorted = sort_by_urgency(arrayJson);
    if (sorted.startsWith('{"error"')) {
      new import_obsidian.Notice("Failed to sort tasks.");
      return;
    }
    new import_obsidian.Notice(`Sorted ${jsons.length} tasks by urgency.`);
    console.log("[task] urgency-sorted tasks:", sorted);
  }
  // ── Settings ──────────────────────────────────────────────────────────────
  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }
  async saveSettings() {
    await this.saveData(this.settings);
  }
};
var TaskSettingTab = class extends import_obsidian.PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }
  display() {
    const { containerEl } = this;
    containerEl.empty();
    new import_obsidian.Setting(containerEl).setName("Desktop companion port").setDesc("WebSocket port the desktop Task app listens on (default 9000).").addText(
      (text) => text.setPlaceholder("9000").setValue(String(this.plugin.settings.desktopPort)).onChange(async (value) => {
        const n = parseInt(value, 10);
        if (!isNaN(n)) {
          this.plugin.settings.desktopPort = n;
          await this.plugin.saveSettings();
        }
      })
    );
    new import_obsidian.Setting(containerEl).setName("Auto-refresh on file change").setDesc("Validate task frontmatter whenever a markdown file is saved.").addToggle(
      (toggle) => toggle.setValue(this.plugin.settings.autoRefresh).onChange(async (value) => {
        this.plugin.settings.autoRefresh = value;
        await this.plugin.saveSettings();
      })
    );
  }
};
function extractFrontmatter(content) {
  if (!content.startsWith("---"))
    return null;
  const end = content.indexOf("\n---", 3);
  if (end === -1)
    return null;
  return content.slice(4, end).trim();
}
